import 'dart:math' as math;import 'package:latlong2/latlong.dart';
class OfflineRouteProgress{const OfflineRouteProgress({required this.remainingKm,required this.etaMinutes,required this.offRouteMetres,required this.progress});final double remainingKm,offRouteMetres,progress;final int etaMinutes;bool get offRoute=>offRouteMetres>300;}
OfflineRouteProgress calculateOfflineRouteProgress({required List<LatLng> route,required LatLng current,double recentSpeedKph=28}){if(route.length<2)return const OfflineRouteProgress(remainingKm:0,etaMinutes:0,offRouteMetres:0,progress:1);final d=Distance();var nearest=0;var nearestM=double.infinity;for(var i=0;i<route.length;i++){final m=d.as(LengthUnit.Meter,current,route[i]);if(m<nearestM){nearestM=m;nearest=i;}}double total=0,remaining=0;for(var i=1;i<route.length;i++){final km=d.as(LengthUnit.Kilometer,route[i-1],route[i]);total+=km;if(i>nearest)remaining+=km;}final p=total<=0?1:(1-remaining/total).clamp(0,1).toDouble();final speed=math.max(12,recentSpeedKph);return OfflineRouteProgress(remainingKm:remaining,etaMinutes:math.max(1,(remaining/speed*60).ceil()),offRouteMetres:nearestM,progress:p);}
